/* GENERATED by build_listings.py from the booking code in design/zermatt-legacy.html - do not edit by hand.
   Book Homes listing pages: availability calendar, date picker, price and Stripe Checkout.
   Marketplace homes use /api/bh/availability + /api/bh/create-checkout; Zermatt Lodge (STAY.legacy) keeps
   /api/availability + /api/create-checkout. The server re-checks and re-prices every booking. Config: window.STAY. */
(function(){
"use strict";
var S = window.STAY || {};
if (!S.id) return;
var $ = function(s, r){ return (r || document).querySelector(s); };
var $$ = function(s, r){ return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
function lock(on){ document.body.style.overflow = on ? "hidden" : ""; }
var LEGACY = !!S.legacy; // Zermatt Lodge keeps its original availability feed and checkout (zermatt-* functions)
var AVAILABILITY_URLS = LEGACY ? ["/api/availability", "/data/availability.json"] : ["/api/bh/availability?listing_id=" + encodeURIComponent(S.id)];
var CHECKOUT_API = LEGACY ? "/api/create-checkout" : "/api/bh/create-checkout";
var CLEANING_FEE = S.cleaning_fee || 0; // shown only; the server re-prices every booking
var MAX_GUESTS = S.max_guests || 16;
var MAX_MONTHS_AHEAD = 12;

function pad(n){ return (n < 10 ? "0" : "") + n; }
function iso(d){ return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()); }
function parse(s){ var p = s.split("-").map(Number); return new Date(p[0], p[1] - 1, p[2]); }
function addDays(s, n){ var d = parse(s); d.setDate(d.getDate() + n); return iso(d); }
function nightsBetween(a, b){ var x = parse(a), y = parse(b); return Math.round((Date.UTC(y.getFullYear(), y.getMonth(), y.getDate()) - Date.UTC(x.getFullYear(), x.getMonth(), x.getDate())) / 864e5); }
var todayIso = iso(new Date());
var validDate = /^\d{4}-\d{2}-\d{2}$/;
var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
var fmtLong = new Intl.DateTimeFormat("en-GB", {weekday:"long", day:"numeric", month:"long", year:"numeric"});
var fmtShort = new Intl.DateTimeFormat("en-GB", {weekday:"short", day:"numeric", month:"short"});
var fmtMonth = new Intl.DateTimeFormat("en-GB", {month:"long", year:"numeric"});
var money = null;
function fmtMoney(n, whole){
  if (!money) money = {};
  if (Number.isInteger(n)) whole = true;
  var k = whole ? "w" : "d";
  if (!money[k]) money[k] = new Intl.NumberFormat("en-GB", {style:"currency", currency: B.currency || "GBP", minimumFractionDigits: whole ? 0 : 2, maximumFractionDigits: 2});
  return money[k].format(n);
}

var B = {map: {}, currency: "GBP", ci: null, co: null, guests: "2", view: null, hover: null, focus: null, loaded: false, pending: null, promo: null};

function day(s){ return B.map[s]; }
function nightOK(s){ var d = day(s); return !!d && d.status === "available" && s >= todayIso; }
function canCheckIn(s){ return nightOK(s) && !day(s).closed_to_arrival; }
function minStay(ci){ var d = day(ci); return Math.max(1, (d && +d.min_stay) || 1); }
function maxCheckout(ci){ var s = ci, n = 0; while (nightOK(s) && n < 400){ s = addDays(s, 1); n++; } return s; }
function canCheckOut(s, ci){ ci = ci || B.ci; if (!ci || s <= ci) return false; return s <= maxCheckout(ci) && nightsBetween(ci, s) >= minStay(ci); }

function fetchAvailability(url){
  return fetch(url, {cache: "no-store", headers: {"Accept": "application/json"}})
    .then(function(r){ if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
    .then(function(j){ if (!j || !Array.isArray(j.days) || !j.days.length) throw new Error("Bad format"); return j; });
}
function loadAvailability(){
  var i = 0;
  function next(){
    if (i >= AVAILABILITY_URLS.length) return Promise.reject(new Error("unavailable"));
    return fetchAvailability(AVAILABILITY_URLS[i++]).catch(next);
  }
  return next();
}
function ingest(j){
  B.map = {};
  j.days.forEach(function(d){ if (d && validDate.test(d.date)) B.map[d.date] = d; });
  B.currency = j.currency || "GBP"; money = null;
  B.loaded = true;
  var live = $("#liveTxt");
  if (live && j.updated){
    var u = new Date(j.updated);
    if (!isNaN(u)) live.textContent = "Updated " + new Intl.DateTimeFormat("en-GB", {day:"numeric", month:"short", hour:"2-digit", minute:"2-digit"}).format(u);
  }
}
function note(msg){ var n = $("#calNote"); if (msg){ n.textContent = msg; n.hidden = false; } else { n.hidden = true; } }

/* Calendar: ONE shared component. Instances: the #book calendar and the date-picker popover/sheet
   used by the hero and sidebar forms. All share the same state (B) and the same availability rules. */
function monthsToShow(inst){ return inst && inst.sheet && window.matchMedia("(max-width:760px)").matches ? 2 : window.matchMedia("(max-width:760px)").matches ? 1 : 2; }
function firstOfMonth(s){ var d = parse(s); return new Date(d.getFullYear(), d.getMonth(), 1); }
function monthDiff(a, b){ return (b.getFullYear() - a.getFullYear()) * 12 + b.getMonth() - a.getMonth(); }
function previewEnd(){
  // While choosing checkout: preview from check-in to the hovered day, stopping at the first unavailable night
  if (!B.ci || B.co || !B.hover || B.hover <= B.ci) return null;
  var lim = maxCheckout(B.ci);
  return B.hover > lim ? lim : B.hover;
}
function dayWhy(s){
  var d = day(s), past = s < todayIso, ok = nightOK(s);
  if (B.ci && !B.co && s > B.ci){
    if (canCheckOut(s)) return "";
    if (s <= maxCheckout(B.ci)) return minStay(B.ci) + "-night minimum";
    if (canCheckIn(s)) return "";
  } else if (canCheckIn(s)) return "";
  if (past) return "Past date";
  if (!ok) return "Unavailable";
  if (d && d.closed_to_arrival) return "No check-in on this day";
  return "Unavailable";
}
function dayEnabled(s){
  if (s === B.co) return true;
  if (B.ci && !B.co && s > B.ci) return canCheckOut(s) || (s > maxCheckout(B.ci) && canCheckIn(s));
  return canCheckIn(s);
}
function makeCal(el, prev, next, statusEl, opts){
  var inst = {el: el, prev: prev, next: next, statusEl: statusEl, view: null, focus: null, sheet: !!(opts && opts.sheet), onPick: opts && opts.onPick};
  el.classList.add("cal-grid");
  el.addEventListener("click", function(e){
    var b = e.target.closest(".day"); if (!b) return;
    var s = b.getAttribute("data-date");
    if (b.getAttribute("aria-disabled") === "true"){ hint(inst, b.getAttribute("data-why")); return; }
    var hadCi = B.ci && !B.co;
    inst.focus = s; selectDate(s);
    var f = el.querySelector('[data-date="' + s + '"]'); if (f) f.focus({preventScroll: true});
    if (inst.onPick) inst.onPick(hadCi && B.co === s);
  });
  el.addEventListener("mouseover", function(e){
    var b = e.target.closest(".day"); var s = b ? b.getAttribute("data-date") : null;
    if (b && b.getAttribute("data-why")) hint(inst, b.getAttribute("data-why")); else status(inst);
    if (!B.ci || B.co) return;
    if (s !== B.hover){ B.hover = s; paintAll(); }
  });
  el.addEventListener("mouseleave", function(){ status(inst); if (B.hover){ B.hover = null; paintAll(); } });
  el.addEventListener("keydown", function(e){
    var b = e.target.closest(".day"); if (!b) return;
    var s = b.getAttribute("data-date"), step = {ArrowLeft:-1, ArrowRight:1, ArrowUp:-7, ArrowDown:7}[e.key];
    if (e.key === "Home") step = -((parse(s).getDay() + 6) % 7);
    if (e.key === "End") step = 6 - ((parse(s).getDay() + 6) % 7);
    if (e.key === "PageUp" || e.key === "PageDown"){ e.preventDefault(); shift(inst, e.key === "PageUp" ? -1 : 1); return; }
    if (step === undefined) return;
    e.preventDefault();
    var t = addDays(s, step);
    if (t < iso(firstOfMonth(todayIso))) return;
    inst.focus = t;
    var t2 = el.querySelector('[data-date="' + t + '"]');
    if (!t2){
      var tm = firstOfMonth(t);
      inst.view = step < 0 ? tm : new Date(tm.getFullYear(), tm.getMonth() - monthsToShow(inst) + 1, 1);
      draw(inst); t2 = el.querySelector('[data-date="' + t + '"]');
    }
    if (t2){
      $$(".day", el).forEach(function(x){ x.tabIndex = -1; }); t2.tabIndex = 0; t2.focus();
      if (B.ci && !B.co){ B.hover = t; paintAll(); }
      if (t2.getAttribute("data-why")) hint(inst, t2.getAttribute("data-why")); else status(inst);
    }
  });
  if (prev) prev.addEventListener("click", function(){ shift(inst, -1); });
  if (next) next.addEventListener("click", function(){ shift(inst, 1); });
  CALS.push(inst);
  return inst;
}
var CALS = [];
function shift(inst, n){ inst.view = new Date(inst.view.getFullYear(), inst.view.getMonth() + n, 1); inst.focus = null; draw(inst); }
function draw(inst){
  if (!B.loaded) return;
  var el = inst.el, n = monthsToShow(inst), now = firstOfMonth(todayIso);
  if (!inst.view) inst.view = firstOfMonth(B.ci || todayIso);
  if (inst.view < now) inst.view = now;
  var maxView = new Date(now.getFullYear(), now.getMonth() + MAX_MONTHS_AHEAD - n + 1, 1);
  if (inst.view > maxView) inst.view = maxView;
  if (inst.prev) inst.prev.disabled = monthDiff(now, inst.view) <= 0;
  if (inst.next) inst.next.disabled = inst.view >= maxView;
  var html = "";
  for (var m = 0; m < n; m++){
    var first = new Date(inst.view.getFullYear(), inst.view.getMonth() + m, 1);
    var dim = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate();
    var lead = (first.getDay() + 6) % 7; // Monday first
    html += '<div class="month"><h3>' + fmtMonth.format(first) + '</h3><div class="wk" aria-hidden="true"><span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span><span>Su</span></div><div class="days">';
    for (var b = 0; b < lead; b++) html += '<span class="blank"></span>';
    for (var dd = 1; dd <= dim; dd++){
      var s = iso(new Date(first.getFullYear(), first.getMonth(), dd)), d = day(s), ok = nightOK(s);
      var price = ok && d && d.price != null ? fmtMoney(+d.price, true) : "";
      html += '<button type="button" class="day" data-date="' + s + '" data-price="' + price + '" tabindex="-1"><span class="dn">' + dd + '</span><small>' + (price || "&nbsp;") + '</small></button>';
    }
    html += '</div></div>';
  }
  el.innerHTML = html;
  paint(inst);
  var t = inst.focus && el.querySelector('[data-date="' + inst.focus + '"]');
  if (!t) t = el.querySelector('.day.sel') || el.querySelector('.day:not([aria-disabled])') || el.querySelector('.day');
  if (t) t.tabIndex = 0;
  status(inst);
}
/* Updates classes only (no re-render), so hover never flickers */
function paint(inst){
  var pe = previewEnd(), end = B.co || pe;
  $$(".day", inst.el).forEach(function(b){
    var s = b.getAttribute("data-date"), d = day(s), past = s < todayIso, ok = nightOK(s);
    var en = dayEnabled(s), why = en ? "" : dayWhy(s);
    var c = "day";
    if (past) c += " past";
    else if (!ok && s !== B.co && !(B.ci && !B.co && canCheckOut(s))) c += " off";
    if (!past && ok && d.closed_to_arrival) c += " nci";
    if (s === todayIso) c += " today";
    if (!en && why.indexOf("minimum") > 0) c += " minst";
    if (s === B.ci) c += " sel start" + (end ? " has-range" : "");
    else if (s === B.co) c += " sel end";
    else if (B.ci && end && s > B.ci && s < end) c += " range";
    else if (!B.co && pe && s === pe) c += " pv-end";
    if (B.ci && end && s === end && s !== B.co) c += "";
    b.className = c;
    if (en) b.removeAttribute("aria-disabled"); else b.setAttribute("aria-disabled", "true");
    if (why){ b.setAttribute("data-why", why); b.title = why; } else { b.removeAttribute("data-why"); b.removeAttribute("title"); }
    if (s === B.ci || s === B.co) b.setAttribute("aria-pressed", "true"); else b.removeAttribute("aria-pressed");
    var price = b.getAttribute("data-price");
    b.setAttribute("aria-label", fmtLong.format(parse(s)) + (price ? ", " + price + " per night" : "") + (s === B.ci ? ", check-in" : s === B.co ? ", checkout" : "") + (why ? ", " + why : ""));
  });
}
function paintAll(){ CALS.forEach(paint); }
function render(){ CALS.forEach(function(i){ if (!i.hidden) draw(i); }); }
var hintTimers = {};
function hint(inst, msg){ if (!inst.statusEl || !msg) return; inst.statusEl.textContent = msg; inst.statusEl.classList.add("hint"); }
function status(inst){
  var st = inst.statusEl; if (!st) return; st.classList.remove("hint");
  if (!B.ci) st.textContent = "Select your check-in date";
  else if (!B.co) st.textContent = "Select checkout" + (minStay(B.ci) > 1 ? " (" + minStay(B.ci) + "-night minimum)" : "");
  else { var n = nightsBetween(B.ci, B.co); st.textContent = fmtShort.format(parse(B.ci)) + " to " + fmtShort.format(parse(B.co)) + " · " + n + (n === 1 ? " night" : " nights"); }
}
function selectDate(s){
  if (!B.ci || B.co){ if (canCheckIn(s)){ B.ci = s; B.co = null; } }
  else if (canCheckOut(s)) B.co = s;
  else if (canCheckIn(s)) B.ci = s;
  B.hover = null;
  afterChange();
}
function afterChange(){
  CALS.forEach(function(i){ if (!i.hidden){ if (!i.el.querySelector(".day")) draw(i); else { paint(i); status(i); } } });
  summary(); syncAll(B.ci, B.co, B.guests);
}
var monthsEl = $("#months");
var mainCal = makeCal(monthsEl, $("#calPrev"), $("#calNext"), $("#calStatus"));
$("#clearDates").addEventListener("click", function(){ B.ci = B.co = null; mainCal.focus = null; hideBkErr(); afterChange(); });
var lastN = monthsToShow(mainCal);
window.addEventListener("resize", function(){ var n = monthsToShow(mainCal); if (n !== lastN){ lastN = n; render(); } });
function focusCalendar(){ var t = monthsEl.querySelector(".day[tabindex='0']"); if (t) t.focus({preventScroll:true}); }
$("#sCiBtn").addEventListener("click", function(){ B.ci = B.co = null; afterChange(); $(".cal-card").scrollIntoView({behavior: reduceMotion ? "auto" : "smooth", block: "start"}); focusCalendar(); });
$("#sCoBtn").addEventListener("click", function(){ if (B.ci){ B.co = null; afterChange(); } $(".cal-card").scrollIntoView({behavior: reduceMotion ? "auto" : "smooth", block: "start"}); focusCalendar(); });

/* Date picker popover (desktop) / bottom sheet (mobile) for the hero and sidebar forms, using the same calendar */
var dp = $("#dp"), dpCal = makeCal($("#dpMonths"), $("#dpPrev"), $("#dpNext"), $("#dpStatus"), {sheet: true, onPick: function(done){ if (done) setTimeout(closeDp, 250); }});
dpCal.hidden = true;
var dpAnchor = null, dpReturn = null;
function isSheet(){ return window.matchMedia("(max-width:760px)").matches; }
function placeDp(){
  if (!dpAnchor || isSheet()){ dp.style.top = dp.style.left = ""; return; }
  var r = dpAnchor.getBoundingClientRect(), w = Math.min(760, window.innerWidth - 32);
  var left = Math.max(16, Math.min(r.left, window.innerWidth - w - 16));
  dp.style.width = w + "px"; dp.style.left = left + "px";
  dp.style.top = (r.bottom + window.scrollY + 10) + "px";
}
function openDp(form, which){
  dpAnchor = form; dpReturn = document.activeElement;
  if (which === "ci"){ /* keep dates, user can re-pick */ }
  dpCal.hidden = false; dpCal.view = firstOfMonth(B.ci || todayIso); dpCal.focus = B.ci && which === "co" ? (B.co || addDays(B.ci, minStay(B.ci))) : (B.ci || null);
  if (which === "ci" && B.ci && B.co){ /* picking again starts a new range */ }
  dp.hidden = false; dp.classList.toggle("sheet", isSheet()); placeDp();
  document.body.classList.add("dp-open"); if (isSheet()) lock(true);
  draw(dpCal);
  requestAnimationFrame(function(){ dp.classList.add("open"); var t = dpCal.el.querySelector(".day[tabindex='0']"); if (t) t.focus({preventScroll: true}); });
}
function closeDp(){
  if (dp.hidden) return;
  dp.classList.remove("open"); dp.hidden = true; dpCal.hidden = true; B.hover = null;
  document.body.classList.remove("dp-open"); lock(false);
  if (dpReturn && dpReturn.focus) dpReturn.focus({preventScroll: true});
}
$("#dpClose").addEventListener("click", closeDp);
$("#dpDone").addEventListener("click", closeDp);
$("#dpClear").addEventListener("click", function(){ B.ci = B.co = null; dpCal.focus = null; afterChange(); });
$("#dpScrim").addEventListener("click", closeDp);
document.addEventListener("keydown", function(e){ if (e.key === "Escape" && !dp.hidden){ e.preventDefault(); closeDp(); } });
document.addEventListener("mousedown", function(e){ if (!dp.hidden && !isSheet() && !dp.contains(e.target) && !(dpAnchor && dpAnchor.contains(e.target))) closeDp(); });
window.addEventListener("resize", function(){ if (!dp.hidden){ dp.classList.toggle("sheet", isSheet()); placeDp(); draw(dpCal); } });

/* Hero + sidebar quick forms: date buttons open the shared picker */
var forms = $$(".date-form");
function syncAll(ci, co, gs){
  forms.forEach(function(f){
    var a = $(".f-ci", f), b = $(".f-co", f);
    a.querySelector("span").textContent = ci ? fmtShort.format(parse(ci)) : "Add date"; a.classList.toggle("ph", !ci);
    b.querySelector("span").textContent = co ? fmtShort.format(parse(co)) : "Add date"; b.classList.toggle("ph", !co);
    if (gs) $(".f-gs", f).value = gs;
  });
}
function showErr(f, on, msg){ var w = f.parentNode.querySelector(".form-err") || $(".form-err", f); if (w){ if (msg) w.textContent = msg; w.classList.toggle("show", on); } }
forms.forEach(function(f){
  var gs = $(".f-gs", f);
  $(".f-ci", f).addEventListener("click", function(){ showErr(f, false); openDp(f, "ci"); });
  $(".f-co", f).addEventListener("click", function(){ showErr(f, false); openDp(f, "co"); });
  gs.addEventListener("change", function(){ B.guests = gs.value; syncAll(B.ci, B.co, B.guests); summary(); });
  f.addEventListener("submit", function(e){
    e.preventDefault();
    B.guests = gs.value; syncAll(B.ci, B.co, B.guests);
    if (!B.ci || !B.co){ openDp(f, B.ci ? "co" : "ci"); return; }
    showErr(f, false); closeDp(); summary();
    mainCal.view = firstOfMonth(B.ci); draw(mainCal);
    goToBooking();
  });
});

/* Price summary */
function quote(){
  if (!B.ci || !B.co) return null;
  var nights = [], s = B.ci, total = 0, missing = false;
  while (s < B.co){ var d = day(s), p = d && d.price != null ? +d.price : null; if (p == null || isNaN(p)) missing = true; else total += p; nights.push({date: s, price: p}); s = addDays(s, 1); }
  var fee = CLEANING_FEE != null && !isNaN(+CLEANING_FEE) ? +CLEANING_FEE : null;
  var disc = 0, n = nights.length, pct = n >= 28 && S.monthly_discount_pct > 0 ? S.monthly_discount_pct : n >= 7 && S.weekly_discount_pct > 0 ? S.weekly_discount_pct : 0;
  if (B.promo && !missing){ disc = Math.round((total * 100) * B.promo.pct / 100) / 100; B.discLabel = B.promo.pct + "% promo code (" + B.promo.code + ", nights only)"; }
  else if (pct && !missing){ disc = Math.round(total * pct) / 100; B.discLabel = (n >= 28 ? "Monthly" : "Weekly") + " discount (" + pct + "%)"; }
  if (fee != null) total += fee;
  return {nights: nights, fee: fee, disc: disc, total: missing ? null : Math.round((total - disc) * 100) / 100};
}
function summary(){
  var ciEl = $("#sCi"), coEl = $("#sCo");
  ciEl.textContent = B.ci ? fmtShort.format(parse(B.ci)) : "Add date"; ciEl.classList.toggle("ph", !B.ci);
  coEl.textContent = B.co ? fmtShort.format(parse(B.co)) : "Add date"; coEl.classList.toggle("ph", !B.co);
  $("#bkGuests").value = B.guests;
  var q = quote(), bd = $("#breakdown"), empty = $("#bdEmpty");
  if (!q){ bd.hidden = true; empty.hidden = false; empty.textContent = B.ci ? "Now choose your checkout date." : "Choose your dates to see the total price."; return; }
  empty.hidden = true; bd.hidden = false;
  var groups = [], html = "";
  q.nights.forEach(function(n){ var g = groups.filter(function(x){ return x.price === n.price; })[0]; if (g) g.count++; else groups.push({price: n.price, count: 1}); });
  if (groups.length > 2 && q.nights.every(function(n){ return n.price != null; })){
    var sum = q.nights.reduce(function(a, n){ return a + n.price; }, 0);
    groups = [{label: q.nights.length + " nights (average " + fmtMoney(Math.round(sum / q.nights.length * 100) / 100) + ")", amount: sum}];
  }
  groups.forEach(function(g){
    if (g.label){ html += '<div class="bd-row"><span>' + g.label + '</span><span>' + fmtMoney(g.amount) + '</span></div>'; return; }
    html += '<div class="bd-row"><span>' + (g.price == null ? "Price on request" : fmtMoney(g.price) + " x " + g.count + (g.count === 1 ? " night" : " nights")) + '</span><span>' + (g.price == null ? "-" : fmtMoney(g.price * g.count)) + '</span></div>';
  });
  if (q.disc > 0) html += '<div class="bd-row bd-disc"><span>' + B.discLabel + '</span><span>-' + fmtMoney(q.disc) + '</span></div>';
  if (q.fee != null) html += '<div class="bd-row"><span>Cleaning fee</span><span>' + fmtMoney(q.fee) + '</span></div>';
  html += '<details><summary>Night-by-night breakdown</summary><ul>' + q.nights.map(function(n){ return '<li><span>' + fmtShort.format(parse(n.date)) + '</span><span>' + (n.price == null ? "-" : fmtMoney(n.price)) + '</span></li>'; }).join("") + '</ul></details>';
  html += '<div class="bd-row bd-total"><span>Total, no booking fees</span><span>' + (q.total == null ? "Confirmed at checkout" : fmtMoney(q.total)) + '</span></div>';
  html += '<p class="bd-note">Includes the cleaning fee. Nothing else is added at checkout.</p>';
  bd.innerHTML = html;
  if (!LEGACY) serverQuote();
}
$("#bkGuests").addEventListener("change", function(){ B.guests = this.value; syncAll(B.ci, B.co, B.guests); });

/* Apply dates coming from the hero / sidebar forms or the URL */
function applyRange(c, o, g){
  if (g && +g >= 1 && +g <= MAX_GUESTS) B.guests = String(+g);
  if (!B.loaded){ B.pending = [c, o, g]; return; }
  hideBkErr();
  if (c && canCheckIn(c)){
    B.ci = c;
    if (o && canCheckOut(o, c)){ B.co = o; note(null); }
    else { B.co = null; if (o) note("Your checkout date isn't available" + (minStay(c) > 1 ? " (minimum stay from " + fmtShort.format(parse(c)) + " is " + minStay(c) + " nights)" : "") + ". Please pick a checkout date on the calendar."); }
  } else if (c){
    B.ci = B.co = null;
    note("Sorry, " + fmtShort.format(parse(c)) + " isn't available for check-in. Please pick another date on the calendar.");
  }
  mainCal.view = c && validDate.test(c) ? firstOfMonth(c) : null; mainCal.focus = B.ci;
  draw(mainCal); afterChange();
}
function goToBooking(){
  $("#book").scrollIntoView({behavior: reduceMotion ? "auto" : "smooth"});
  setTimeout(function(){ $("#bookH").focus({preventScroll:true}); }, reduceMotion ? 0 : 450);
}

/* Reserve -> POST /api/create-checkout -> redirect to Stripe Checkout */
var rf = $("#reserveForm"), rBtn = $("#reserveBtn"), bkErr = $("#bkErr");
function hideBkErr(){ bkErr.hidden = true; bkErr.innerHTML = ""; }
function showBkErr(title, msg){
  bkErr.innerHTML = "<b></b><span></span>" + (LEGACY ? " Need help? Email <a href=\"mailto:cs@zugati.co.uk\">cs@zugati.co.uk</a>." : "");
  bkErr.querySelector("b").textContent = title; bkErr.querySelector("span").textContent = msg;
  bkErr.hidden = false;
}
function setBusy(on){ rBtn.disabled = on; rBtn.setAttribute("aria-busy", on ? "true" : "false"); rBtn.textContent = on ? "Taking you to secure checkout..." : "Reserve"; }
rf.addEventListener("submit", function(e){
  e.preventDefault(); hideBkErr();
  if (!B.ci || !B.co){ showBkErr("Choose your dates first.", "Pick a check-in and checkout date on the calendar."); focusCalendar(); return; }
  var name = $("#bkName"), email = $("#bkEmail"), phone = $("#bkPhone"), bad = null;
  [[name, name.value.trim().length >= 2], [email, /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim())], [phone, phone.value.replace(/[^\d]/g, "").length >= 7]].forEach(function(p){
    p[0].setAttribute("aria-invalid", p[1] ? "false" : "true"); if (!p[1] && !bad) bad = p[0];
  });
  if (bad){ showBkErr("Please check your details.", "We need your full name, a valid email address and a phone number."); bad.focus(); return; }
  setBusy(true);
  var payload = {checkIn: B.ci, checkOut: B.co, guests: +B.guests, name: name.value.trim(), email: email.value.trim(), phone: phone.value.trim()};
  if (LEGACY){ var pin = $("#bkPromo"), promoTyped = pin ? cleanCode(pin.value) : ""; if (promoTyped) payload.promo_code = promoTyped; }
  else {
    payload.listing_id = S.id;
    var co = $("#bkCompany"), coTick = $("#bkReceipt");
    if (coTick && coTick.checked && co && co.value.trim()) payload.company = co.value.trim();
    if (B.pets) payload.pets = +B.pets;
  }
  fetch(CHECKOUT_API, {method: "POST", headers: {"Content-Type": "application/json", "Accept": "application/json"}, body: JSON.stringify(payload)})
    .then(function(r){ return r.json().catch(function(){ return {}; }).then(function(j){ return {ok: r.ok, status: r.status, j: j}; }); })
    .then(function(res){
      if (res.status === 503 || (res.j && res.j.code === "BOOKING_NOT_OPEN")){
        setBusy(false);
        showBkErr("Online booking opens shortly.", "Nothing has been booked or charged.");
        return;
      }
      if (res.j && res.j.code === "NOT_AVAILABLE") reload();
      if (res.j && res.j.code === "PROMO_INVALID"){
        setBusy(false); setPromo(null); promoMsg(res.j.error || "That promo code is not valid.", false);
        showBkErr("That promo code didn't work.", "Nothing has been booked or charged. Remove the code to book at the normal price, or check it and try again.");
        return;
      }
      var url = res.j && res.j.url;
      if (res.ok && typeof url === "string" && /^(https:\/\/|\/)/.test(url)){ window.location.assign(url); return; }
      throw new Error(res.j && typeof res.j.error === "string" ? res.j.error : "");
    })
    .catch(function(err){
      setBusy(false);
      showBkErr("We couldn't start checkout.", (err && err.message ? err.message + " " : "") + "Your dates have not been booked and you have not been charged. Please try again in a moment.");
    });
});
["bkName", "bkEmail", "bkPhone"].forEach(function(id){ $("#" + id).addEventListener("input", function(){ this.removeAttribute("aria-invalid"); }); });
window.addEventListener("pageshow", function(){ setBusy(false); });
function reload(){ loadAvailability().then(function(j){ ingest(j); B.co = null; afterChange(); }).catch(function(){}); }

/* Promo code (Zermatt Lodge checkout only): checked on the server, applied to the nights only */
function cleanCode(v){ return String(v || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 30); }
function promoMsg(t, ok){ var o = $("#promoMsg"); if (!o) return; o.textContent = t || ""; o.hidden = !t; o.className = "promo-msg " + (ok ? "ok" : "err"); }
function setPromo(p){ B.promo = p; summary(); }
function applyPromo(code){
  var pin = $("#bkPromo"), pb = $("#promoBtn");
  code = cleanCode(code);
  if (!pin || !code){ setPromo(null); promoMsg("", true); return Promise.resolve(false); }
  pin.value = code; pb.disabled = true;
  var det = pin.closest("details"); if (det) det.open = true;
  return fetch(CHECKOUT_API, {method: "POST", headers: {"Content-Type": "application/json", "Accept": "application/json"}, body: JSON.stringify({validate_promo: code})})
    .then(function(r){ return r.json(); })
    .then(function(j){
      pb.disabled = false;
      if (j && j.valid && +j.percent_off > 0){ setPromo({code: j.code, pct: +j.percent_off}); promoMsg(j.percent_off + "% off the nightly rate applied.", true); return true; }
      setPromo(null); promoMsg((j && j.error) || "Sorry, that promo code is not valid.", false); return false;
    })
    .catch(function(){ pb.disabled = false; setPromo(null); promoMsg("We couldn't check that code just now. You can still book, and we'll check it at checkout.", false); return false; });
}
(function(){
  var pin = $("#bkPromo"), pb = $("#promoBtn");
  if (!pin || !LEGACY) return;
  pb.addEventListener("click", function(){ applyPromo(pin.value); });
  pin.addEventListener("keydown", function(e){ if (e.key === "Enter"){ e.preventDefault(); applyPromo(pin.value); } });
  pin.addEventListener("input", function(){ if (B.promo && cleanCode(pin.value) !== B.promo.code){ setPromo(null); promoMsg("", true); } });
})();
window.BH_applyPromo = function(code){ showDetails(false); return applyPromo(code); };
window.BH_goToBooking = function(){ var c = $("#bookcard"); if (c) c.scrollIntoView({behavior: reduceMotion ? "auto" : "smooth", block: "center"}); };

/* "Email me if these dates free up" */
var af = $("#alertForm");
if (af) af.addEventListener("submit", function(e){
  e.preventDefault();
  var em = $("#alertEmail").value.trim(), out = $("#alertMsg");
  var ci = $("#alertCi").value || B.ci, co = $("#alertCo").value || B.co;
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(em)){ out.textContent = "Please enter a valid email."; return; }
  if (!ci || !co || co <= ci){ out.textContent = "Choose the dates you want first."; return; }
  out.textContent = "Saving...";
  fetch("/api/bh/listings", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({action: "alert", email: em, slug: S.slug, check_in: ci, check_out: co, guests: +B.guests, consent: false})})
    .then(function(r){ return r.json().then(function(j){ return {ok: r.ok, j: j}; }); })
    .then(function(r){ out.textContent = r.ok ? "Done. We'll email you once if " + fmtShort.format(parse(ci)) + " to " + fmtShort.format(parse(co)) + " can be booked." : (r.j.error || "Please try again."); })
    .catch(function(){ out.textContent = "Please try again."; });
});
var aci = $("#alertCi"), aco = $("#alertCo");
if (aci){ aci.min = todayIso; aco.min = todayIso; aci.addEventListener("change", function(){ aco.min = aci.value; }); }

var rt = $("#bkReceipt");
if (rt) rt.addEventListener("change", function(){ $("#bkCompanyWrap").hidden = !rt.checked; if (rt.checked) $("#bkCompany").focus(); });

/* Reserve in two steps, like the big platforms: dates first, then name, email and phone */
function showDetails(focus){
  var w = $("#detWrap"); if (!w) return;
  if (w.hidden){ w.hidden = false; }
  if (focus){ var n = $("#bkName"); setTimeout(function(){ n.focus({preventScroll: true}); n.scrollIntoView({behavior: reduceMotion ? "auto" : "smooth", block: "center"}); }, 30); }
}
document.addEventListener("submit", function(e){
  if (e.target !== rf) return;
  if (!B.ci || !B.co){ e.preventDefault(); e.stopImmediatePropagation(); hideBkErr(); openDp($("#bookcard"), B.ci ? "co" : "ci"); return; }
  var w = $("#detWrap");
  if (w && w.hidden){ e.preventDefault(); e.stopImmediatePropagation(); showDetails(true); }
}, true);

/* Price header on the card and the phone bottom bar */
var fmtD = new Intl.DateTimeFormat("en-GB", {day: "numeric", month: "short"});
function rangeTxt(){ return B.ci && B.co ? fmtD.format(parse(B.ci)) + " to " + fmtD.format(parse(B.co)) : ""; }
function mbar(){
  var q = quote(), el = $("#mbookPrice"), cp = $("#cardPrice"), from = cp ? cp.getAttribute("data-from") : "";
  var has = q && q.total != null;
  /* marketplace homes: once the server has priced these dates (extra guests, pets, discounts), show its total here too */
  if (has && B.sq && B.sq.key === [B.ci, B.co, B.guests, B.pets || 0].join("|")) q.total = B.sq.total;
  if (cp) cp.innerHTML = has ? "<b>" + fmtMoney(q.total) + "</b> <span>total for " + q.nights.length + " night" + (q.nights.length === 1 ? "" : "s") + "</span>"
    : from ? '<span class="from">From</span> <b>' + from + "</b> <span>night</span>" : "<b>Add dates</b> <span>for prices</span>";
  if (el) el.innerHTML = has ? "<b>" + fmtMoney(q.total) + " total</b><small>" + rangeTxt() + ", no booking fees</small>"
    : (from ? "<b>From " + from + " night</b>" : "<b>Add dates</b>") + "<small>" + (B.ci ? "Choose your checkout date" : "Add dates for the total") + "</small>";
  var rb = $("#reserveBtn"); if (rb && !rb.disabled) rb.textContent = has ? "Reserve" : "Check availability";
}
var mb = $("#mbookBtn");
if (mb) mb.addEventListener("click", function(){
  if (B.ci && B.co){ showDetails(true); }
  else openDp($("#bookcard"), B.ci ? "co" : "ci");
});
var _summary = summary;
summary = function(){ _summary(); mbar(); };
var _setBusy = setBusy;
setBusy = function(on){ _setBusy(on); if (!on) mbar(); };

/* Host booking rules: checkout only on the host's checkout days (ISO weekdays, 1 = Monday). Check-in days come from
   closed_to_arrival in the availability feed. */
function isoDow(s){ return (parse(s).getDay() + 6) % 7 + 1; }
if (S.checkout_days && S.checkout_days.length){
  var _cco = canCheckOut, _why = dayWhy;
  canCheckOut = function(s, ci){ return _cco(s, ci) && S.checkout_days.indexOf(isoDow(s)) >= 0; };
  dayWhy = function(s){
    if (B.ci && !B.co && s > B.ci && _cco(s) && S.checkout_days.indexOf(isoDow(s)) < 0) return "No checkout on this day";
    return _why(s);
  };
}
/* Pets: only on homes that allow them; the server quote adds the pet fee */
var petSel = $("#bkPets");
if (petSel){
  var qp = new URLSearchParams(location.search).get("pets");
  if (/^[1-3]$/.test(qp || "")){ petSel.value = qp; B.pets = +qp; }
  petSel.addEventListener("change", function(){ B.pets = +this.value || 0; summary(); });
}
/* Boot */
/* Marketplace homes: the server's quote is the price Stripe will charge (extra guests, pets, discounts, cleaning). */
var SQ = 0;
function serverQuote(){
  var my = ++SQ, key = [B.ci, B.co, B.guests, B.pets || 0].join("|");
  fetch("/api/bh/availability?listing_id=" + encodeURIComponent(S.id) + "&check_in=" + B.ci + "&check_out=" + B.co + "&guests=" + encodeURIComponent(B.guests) + "&pets=" + (B.pets || 0), {headers: {"Accept": "application/json"}})
    .then(function(r){ return r.json(); }).then(function(j){
      if (my !== SQ || key !== [B.ci, B.co, B.guests, B.pets || 0].join("|")) return;
      var bd = $("#breakdown"); if (!bd) return;
      if (!j.ok){ if (j.error) bd.innerHTML = '<p class="bd-note bd-err">' + j.error.replace(/[&<>"]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]; }) + "</p>"; return; }
      var q = j.quote, h = "";
      B.sq = {key: key, total: q.total_pence / 100}; mbar();
      q.lines.forEach(function(l){ h += '<div class="bd-row' + (l.pence < 0 ? " bd-disc" : "") + '"><span>' + l.label.replace(/[&<>]/g, "") + "</span><span>" + (l.pence < 0 ? "-" : "") + fmtMoney(Math.abs(l.pence) / 100) + "</span></div>"; });
      h += '<details><summary>Night-by-night breakdown</summary><ul>' + q.nightly.map(function(n){ return "<li><span>" + fmtShort.format(parse(n.date)) + "</span><span>" + fmtMoney(n.price) + "</span></li>"; }).join("") + "</ul></details>";
      h += '<div class="bd-row bd-total"><span>Total, no booking fees</span><span>' + fmtMoney(q.total_pence / 100) + "</span></div>";
      h += '<p class="bd-note">No guest service fee. This is exactly what you pay at checkout.</p>';
      bd.innerHTML = h;
    }).catch(function(){});
}
// Back from Stripe without paying: free the held dates first, so they show as available again
function releaseHold(){
  var q0 = new URLSearchParams(location.search), hold = q0.get("hold");
  if (LEGACY || !q0.get("cancelled") || !hold || !/^[0-9a-f-]{36}$/i.test(hold)) return Promise.resolve();
  return fetch(CHECKOUT_API, {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({release_hold: hold})}).catch(function(){});
}
releaseHold().then(loadAvailability).then(function(j){
  ingest(j);
  var q = new URLSearchParams(location.search);
  var c = q.get("check_in") || q.get("checkIn"), o = q.get("check_out") || q.get("checkOut"), g = q.get("guests");
  if (!(g && /^\d{1,2}$/.test(g) && +g >= 1 && +g <= MAX_GUESTS)) g = null;
  if (B.pending){ applyRange.apply(null, B.pending); B.pending = null; }
  else if (c && validDate.test(c) && c >= todayIso){ applyRange(c, o && validDate.test(o) ? o : null, g); }
  else { if (g) B.guests = g; render(); summary(); }
  mbar();
  var pc = cleanCode(q.get("promo")); if (pc && LEGACY) applyPromo(pc);
  if (q.get("cancelled")) showBkErr("Payment cancelled.", "Your dates are not booked and you have not been charged.");
}).catch(function(){
  $("#months").innerHTML = '<p class="bd-empty">Live availability could not be loaded. Please refresh the page.</p>';
});
})();
